     <svg aria-hidden="true" viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.6">
       <path d="M12 16V4m0 0L7.5 8.5M12 4l4.5 4.5M4 15.5V20h16v-4.5" />
     </svg>
   );
 }
